16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.AddressNormalizer;
20	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private java.time.LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "household_member_count")
68	    private Integer householdMemberCount;
69	
70	    public String getCustomerCode() {
71	        return this.customerCode;
72	    }
73	
74	    public Integer getNamesakeCount() {
75	        return this.namesakeCount;
76	    }
77	
78	    public void setNamesakeCount(Integer namesakeCount) {
79	        this.namesakeCount = namesakeCount;
80	    }
81	
82	    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
83	    public void assignNamesakeCount(Collection<Owner> existingOwners) {
84	        int count = 0;
85	        for (Owner other : existingOwners) {
86	            if (getFirstName().equalsIgnoreCase(other.getFirstName())
87	                && getLastName().equalsIgnoreCase(other.getLastName())) {
88	                count++;
89	            }
90	        }
91	        this.namesakeCount = count;
92	        assignHouseholdMemberCount(existingOwners);
93	    }
94	
95	    public Integer getHouseholdMemberCount() {
96	        return this.householdMemberCount;
97	    }
98	
99	    /** Record how many owners (this one included) share this owner's household after this create. */
100	    public void assignHouseholdMemberCount(Collection<Owner> existingOwners) {
101	        int count = 1;
102	        for (Owner other : existingOwners) {
103	            if (householdId != null && householdId.equals(other.getHouseholdId())) {
104	                count++;
105	            }
106	        }
107	        this.householdMemberCount = count;
108	    }
109	
110	    public String getHouseholdId() {
111	        return this.householdId;
112	    }
113	
114	    public void setHouseholdId(String householdId) {
115	        this.householdId = householdId;
116	    }
117	
118	    /** Assign the '<CITY3>-<LAST3>-<NNNN>' customer code, where NNNN is one more than {@code cityCount}. */
119	    public void assignCustomerCode(int cityCount) {
120	        String city3 = getCity().substring(0, Math.min(3, getCity().length())).toUpperCase(Locale.ROOT);
121	        String last3 = getLastName().substring(0, Math.min(3, getLastName().length())).toUpperCase(Locale.ROOT);
122	        this.customerCode = String.format("%s-%s-%04d", city3, last3, cityCount + 1);
123	    }
124	
125	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
126	    private Set<Pet> pets;
127	
128	    public java.time.LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public String getAddress() {
137	        return this.address;
138	    }
139	
140	    /** Store the address normalized so create persists and returns the canonical form. */
141	    public void setAddress(String address) {
142	        this.address = AddressNormalizer.normalize(address);
143	    }
144	
145	    public String getCity() {
146	        return this.city;
147	    }
148	
149	    public void setCity(String city) {
150	        this.city = city;
151	    }
152	
153	    public String getTelephone() {
154	        return this.telephone;
155	    }
156	
157	    /** Store the telephone in E.164 form so create and update persist and return it normalized. */
158	    public void setTelephone(String telephone) {
159	        this.telephone = TelephoneNormalizer.toE164(telephone);
160	    }
161	
162	    public String getEmail() {
163	        return this.email;
164	    }
165	
166	    /** Store the address lower-cased so it is persisted and returned normalized. */
167	    public void setEmail(String email) {
168	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
169	    }
170	
171	    protected Set<Pet> getPetsInternal() {
172	        if (this.pets == null) {
173	            this.pets = new HashSet<>();
174	        }
175	        return this.pets;
176	    }
177	
178	    protected void setPetsInternal(Set<Pet> pets) {
179	        this.pets = pets;
180	    }
181	
182	    public List<Pet> getPets() {
183	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
184	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
185	        return Collections.unmodifiableList(sortedPets);
186	    }
187	
188	    public void setPets(List<Pet> pets) {
189	        this.pets = new HashSet<>(pets);
190	    }
191	
192	    public void addPet(Pet pet) {
193	        getPetsInternal().add(pet);
194	        pet.setOwner(this);
195	    }
196	
197	    /**
198	     * Return the Pet with the given name, or null if none found for this Owner.
199	     *
200	     * @param name to test
201	     * @return true if pet name is already in use
202	     */
203	    public Pet getPet(String name) {
204	        return getPet(name, false);
205	    }
206	
207	    /**
208	     * Return the Pet with the given name, or null if none found for this Owner.
209	     *
210	     * @param name to test
211	     * @return true if pet name is already in use
212	     */
213	    public Pet getPet(String name, boolean ignoreNew) {
214	        name = name.toLowerCase();
215	        for (Pet pet : getPetsInternal()) {
216	            if (!ignoreNew || !pet.isNew()) {
217	                String compName = pet.getName();
218	                compName = compName.toLowerCase();
219	                if (compName.equals(name)) {
220	                    return pet;
221	                }
222	            }
223	        }
224	        return null;
225	    }
226	
227	    public Pet getPet(Integer petId) {
228	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
229	    }
230	
231	    @Override
232	    public String toString() {
233	        return new ToStringCreator(this)
234	
235	            .append("id", this.getId())
236	            .append("new", this.isNew())
237	            .append("lastName", this.getLastName())
238	            .append("firstName", this.getFirstName())
239	            .append("address", this.address)
240	            .append("city", this.city)
241	            .append("telephone", this.telephone)
242	            .toString();
243	    }
244	}
